/**
 * Custom Worker 엔트리 — OpenNext가 생성한 fetch 핸들러를 재사용하면서,
 * fetch 외 핸들러/export(여기서는 Workflow 클래스)를 추가한다.
 *
 * 근거: OpenNext 공식 문서 `howtos/custom-worker`
 *   "The worker generated by the Cloudflare adapter only exports a fetch handler.
 *    Sometimes your application needs to expose another type of handler... This can be
 *    achieved by creating a custom worker."
 *
 * ⚠️ `.open-next/worker.js`는 **`opennextjs-cloudflare build` 시점에 생성**된다.
 *    그래서 `npm run build`(next build)에는 이 파일이 없고, import는 ts 주석으로 넘긴다.
 *    배포(`npm run deploy`)는 opennext build → wrangler deploy 순서라 문제없다.
 *    `@ts-expect-error` 대신 `@ts-ignore`를 쓰는 이유: 배포 빌드에서는 모듈이 **실제로 존재**해서
 *    expect-error가 "사용되지 않은 지시"로 에러가 된다.
 */

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js`는 빌드 산출물 (타입 없음)
import { default as openNextHandler } from "./.open-next/worker.js";

// ISR/태그 캐시가 Durable Object를 쓴다 → re-export 필수
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore 빌드 산출물
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";

// 파이프라인 오케스트레이터 (wrangler.jsonc 의 workflows[].class_name 과 일치해야 함)
export { BatchPipeline } from "./src/workflows/batchPipeline";

const worker = {
    fetch: openNextHandler.fetch,
};

export default worker;
